import json
import os
import subprocess
import sys
import time
import uuid
from datetime import datetime, timezone
from pathlib import Path

ROOT = Path('/home/r/dev/minor/stackd')
sys.path.insert(0, str(ROOT / 'scripts/aws'))
from aws_cli import run, result

ACCOUNT = '000000000000'
REGION = 'us-west-2'
PREFIX = 'sd-sfn-vars-' + uuid.uuid4().hex[:10]
OUT = ROOT / 'testdata/aws/stepfunctions/variable_limits.json'
ROLE = PREFIX + '-execution'
ROLE_ARN = f'arn:aws:iam::{ACCOUNT}:role/{ROLE}'
ENV = dict(os.environ)
ENV.update(AWS_REGION=REGION, AWS_DEFAULT_REGION=REGION, AWS_MAX_ATTEMPTS='1', AWS_RETRY_MODE='standard', AWS_IGNORE_CONFIGURED_ENDPOINT_URLS='true', AWS_PAGER='')
for key in list(ENV):
    if key.startswith('AWS_ENDPOINT_URL'):
        ENV.pop(key)
CAPTURE = {
    'service': 'stepfunctions', 'region': REGION, 'account': ACCOUNT,
    'started_at': datetime.now(timezone.utc).isoformat(),
    'sources': [
        {'path': __file__, 'content': Path(__file__).read_text()},
        {'path': 'scripts/aws/aws_cli.py', 'content': (ROOT / 'scripts/aws/aws_cli.py').read_text()},
        {'url': 'https://docs.aws.amazon.com/step-functions/latest/dg/workflow-variables.html'},
        {'url': 'https://docs.aws.amazon.com/step-functions/latest/dg/service-quotas.html'},
        {'url': 'https://docs.aws.amazon.com/step-functions/latest/dg/sfn-best-practices.html#bp-history-limit'},
        {'url': 'https://docs.aws.amazon.com/step-functions/latest/apireference/API_TestState.html'},
        {'url': 'https://docs.aws.amazon.com/step-functions/latest/apireference/API_GetExecutionHistory.html'},
        {'url': 'https://aws.amazon.com/step-functions/pricing/'}
    ],
    'transport': {'cli_version': subprocess.run(['aws', '--version'], capture_output=True, text=True, check=True).stdout.strip(), 'implementation': 'scripts/aws/aws_cli.py run/result', 'automatic_retries': 0, 'connect_timeout_seconds': 10, 'read_timeout_seconds': 30, 'process_timeout_seconds': 45, 'AWS_IGNORE_CONFIGURED_ENDPOINT_URLS': 'true', 'region': REGION, 'endpoints': {'stepfunctions': f'https://states.{REGION}.amazonaws.com', 'sts': f'https://sts.{REGION}.amazonaws.com', 'iam': 'https://iam.amazonaws.com'}, 'iam_signing_region': 'us-east-1'},
    'bounds': {'maximum_history_cap_exceeding_executions': 1, 'history_loop_iterations': 7000, 'maximum_history_execution_transitions': 14002, 'maximum_all_workflow_transitions': 14052, 'workflow_timeout_seconds': 180, 'maximum_test_state_calls': 11, 'standard_transition_price_per_1000_usd': 0.025, 'conservative_maximum_transition_cost_usd': 0.36, 'no_integrated_tasks': True, 'no_logs_or_customer_kms_keys': True, 'account_settings_modified': False, 'role_permissions_added': False},
    'owned_resources': {'prefix': PREFIX, 'role': ROLE_ARN, 'state_machines': {}, 'executions': {}},
    'definitions': {}, 'observations': [], 'findings': [], 'limitations': [],
    'cleanup': {'executions_terminal': {}, 'state_machines_absent': {}, 'roles_absent': {}, 'errors': []}
}
MACHINES = []
EXECUTIONS = []
ROLE_CREATED = False

def save():
    OUT.write_text(json.dumps(CAPTURE, indent=2, ensure_ascii=False) + '\n')

def observe(label, service, operation, parameters):
    endpoint = CAPTURE['transport']['endpoints'][service]
    options = ['--region', 'us-east-1' if service == 'iam' else REGION, '--endpoint-url', endpoint, '--no-paginate', '--cli-connect-timeout', '10', '--cli-read-timeout', '30']
    start = time.time()
    process = run(service, operation, parameters, ENV, options=options, timeout=45)
    decoded = result(process, cli_message=None)
    entry = {'label': label, 'service': service, 'operation': operation, 'input': parameters, 'request_started_ms': int(start * 1000), 'request_finished_ms': int(time.time() * 1000), 'result': decoded}
    CAPTURE['observations'].append(entry)
    save()
    print(json.dumps({'label': label, 'code': decoded['code'], 'status': decoded.get('output', {}).get('status'), 'error': decoded.get('output', {}).get('error'), 'event_ids': [e['id'] for e in decoded.get('output', {}).get('events', [])]}), flush=True)
    return decoded

def output(observation):
    if observation['code'] != 'Success':
        raise RuntimeError(json.dumps(observation))
    return observation['output']

def create(label, definition):
    CAPTURE['definitions'][label] = definition
    name = PREFIX + '-' + label
    arn = f'arn:aws:states:{REGION}:{ACCOUNT}:stateMachine:{name}'
    absence = observe(label + '-preflight-absence', 'stepfunctions', 'describe-state-machine', {'stateMachineArn': arn})
    if absence['code'] != 'StateMachineDoesNotExist':
        raise RuntimeError('Owned state machine name not absent: ' + name)
    result = output(observe(label + '-create', 'stepfunctions', 'create-state-machine', {'name': name, 'definition': json.dumps(definition, separators=(',', ':')), 'roleArn': ROLE_ARN, 'type': 'STANDARD'}))
    MACHINES.append(result['stateMachineArn'])
    CAPTURE['owned_resources']['state_machines'][label] = result['stateMachineArn']
    return result['stateMachineArn']

def execute(label, definition):
    arn = create(label, definition)
    started = output(observe(label + '-start', 'stepfunctions', 'start-execution', {'stateMachineArn': arn, 'name': label, 'input': '{}'}))
    execution = started['executionArn']
    EXECUTIONS.append(execution)
    CAPTURE['owned_resources']['executions'][label] = execution
    deadline = time.monotonic() + 205
    attempt = 0
    while True:
        terminal = output(observe(label + '-describe-' + str(attempt), 'stepfunctions', 'describe-execution', {'executionArn': execution}))
        if terminal['status'] != 'RUNNING':
            return execution, terminal
        if time.monotonic() > deadline:
            raise RuntimeError('Owned execution exceeded observation deadline: ' + label)
        attempt += 1
        time.sleep(3 if label == 'history-cap' else 1)

def workflow(states, start):
    return {'QueryLanguage': 'JSONata', 'TimeoutSeconds': 180, 'StartAt': start, 'States': states}

def pad(count):
    return "{% $pad('', " + str(count) + ", 'x') %}"

try:
    identity = output(observe('identity', 'sts', 'get-caller-identity', {}))
    if identity['Account'] != ACCOUNT:
        raise RuntimeError('Unexpected native account; no resources created')
    baseline = {'Type': 'Pass', 'QueryLanguage': 'JSONata', 'Assign': {'x': 'small'}, 'Output': {'ok': True}, 'End': True}
    observe('test-assignment-small-debug', 'stepfunctions', 'test-state', {'definition': json.dumps(baseline, separators=(',', ':')), 'input': '{}', 'inspectionLevel': 'DEBUG'})
    for count in [262136, 262137, 262142, 262143, 262144, 262145]:
        definition = {'Type': 'Pass', 'QueryLanguage': 'JSONata', 'Assign': {'x': pad(count)}, 'Output': {'ok': True}, 'End': True}
        observe('test-single-assignment-' + str(count), 'stepfunctions', 'test-state', {'definition': json.dumps(definition, separators=(',', ':')), 'input': '{}', 'inspectionLevel': 'INFO'})
    for count in [131060, 131070, 131071, 131072]:
        definition = {'Type': 'Pass', 'QueryLanguage': 'JSONata', 'Assign': {'x': pad(count), 'y': pad(count)}, 'Output': {'ok': True}, 'End': True}
        observe('test-combined-assignment-' + str(count), 'stepfunctions', 'test-state', {'definition': json.dumps(definition, separators=(',', ':')), 'input': '{}', 'inspectionLevel': 'INFO'})
    if observe('role-preflight-absence', 'iam', 'get-role', {'RoleName': ROLE})['code'] != 'NoSuchEntity':
        raise RuntimeError('Owned IAM role name not absent')
    trust = {'Version': '2012-10-17', 'Statement': [{'Effect': 'Allow', 'Principal': {'Service': 'states.amazonaws.com'}, 'Action': 'sts:AssumeRole', 'Condition': {'StringEquals': {'aws:SourceAccount': ACCOUNT}, 'ArnLike': {'aws:SourceArn': f'arn:aws:states:{REGION}:{ACCOUNT}:stateMachine:{PREFIX}-*'}}}]}
    output(observe('role-create', 'iam', 'create-role', {'RoleName': ROLE, 'AssumeRolePolicyDocument': json.dumps(trust), 'Description': 'Owned bounded Step Functions variable and history limits probe'}))
    ROLE_CREATED = True
    time.sleep(10)
    small = workflow({'Assign': {'Type': 'Pass', 'Assign': {'small': {'value': 7, 'text': 'native'}}, 'Next': 'Read'}, 'Read': {'Type': 'Pass', 'Output': '{% $small %}', 'End': True}}, 'Assign')
    small_arn, small_terminal = execute('small-history', small)
    for include in [True, False]:
        observe('small-history-include-data-' + str(include).lower(), 'stepfunctions', 'get-execution-history', {'executionArn': small_arn, 'includeExecutionData': include, 'maxResults': 100})
    scope = workflow({'One': {'Type': 'Pass', 'Assign': {'one': pad(200000)}, 'Next': 'Two'}, 'Two': {'Type': 'Pass', 'Assign': {'two': pad(200000)}, 'Next': 'Lengths'}, 'Lengths': {'Type': 'Pass', 'Output': {'one': '{% $length($one) %}', 'two': '{% $length($two) %}', 'sum': '{% $length($one) + $length($two) %}'}, 'End': True}}, 'One')
    execute('scope-over-256k', scope)
    total_states = {}
    for i in range(1, 44):
        total_states['Assign' + str(i)] = {'Type': 'Pass', 'Assign': {'v' + str(i): pad(250000)}, 'Next': 'Assign' + str(i + 1) if i < 43 else 'Lengths'}
    total_states['Lengths'] = {'Type': 'Pass', 'Output': {'variables': 43, 'sum': '{% ' + ' + '.join('$length($v' + str(i) + ')' for i in range(1, 44)) + ' %}'}, 'End': True}
    total_arn, total_terminal = execute('total-over-10m', workflow(total_states, 'Assign1'))
    observe('total-over-10m-final-history', 'stepfunctions', 'get-execution-history', {'executionArn': total_arn, 'includeExecutionData': False, 'reverseOrder': True, 'maxResults': 2})
    history = workflow({'Init': {'Type': 'Pass', 'Output': {'n': 0}, 'Next': 'Increment'}, 'Increment': {'Type': 'Pass', 'Output': {'n': '{% $states.input.n + 1 %}'}, 'Next': 'Check'}, 'Check': {'Type': 'Choice', 'Choices': [{'Condition': '{% $states.input.n < 7000 %}', 'Next': 'Increment'}], 'Default': 'Done'}, 'Done': {'Type': 'Succeed'}}, 'Init')
    history_arn, history_terminal = execute('history-cap', history)
    observe('history-cap-final-history', 'stepfunctions', 'get-execution-history', {'executionArn': history_arn, 'includeExecutionData': True, 'reverseOrder': True, 'maxResults': 12})
    observe('history-cap-first-history', 'stepfunctions', 'get-execution-history', {'executionArn': history_arn, 'includeExecutionData': False, 'maxResults': 3})
except BaseException as error:
    CAPTURE['workflow_failure'] = type(error).__name__ + ': ' + str(error)
    CAPTURE['limitations'].append('Capture stopped at the recorded workflow_failure; unperformed cases are not native outcomes.')
    print(CAPTURE['workflow_failure'], flush=True)
finally:
    for execution in EXECUTIONS:
        try:
            value = output(observe('cleanup-describe-' + execution.rsplit(':', 1)[-1], 'stepfunctions', 'describe-execution', {'executionArn': execution}))
            if value['status'] == 'RUNNING':
                output(observe('cleanup-stop-' + execution.rsplit(':', 1)[-1], 'stepfunctions', 'stop-execution', {'executionArn': execution, 'error': 'OwnedProbeCleanup', 'cause': 'Bounded native probe cleanup'}))
                value = output(observe('cleanup-terminal-' + execution.rsplit(':', 1)[-1], 'stepfunctions', 'describe-execution', {'executionArn': execution}))
            CAPTURE['cleanup']['executions_terminal'][execution] = value['status']
        except BaseException as error:
            CAPTURE['cleanup']['errors'].append(type(error).__name__ + ': ' + str(error))
    for arn in reversed(MACHINES):
        try:
            output(observe('cleanup-delete-' + arn.rsplit(':', 1)[-1], 'stepfunctions', 'delete-state-machine', {'stateMachineArn': arn}))
        except BaseException as error:
            CAPTURE['cleanup']['errors'].append(type(error).__name__ + ': ' + str(error))
    pending = set(MACHINES)
    deadline = time.monotonic() + 180
    attempt = 0
    while pending and time.monotonic() < deadline:
        for arn in sorted(pending):
            try:
                absent = observe('cleanup-absence-' + arn.rsplit(':', 1)[-1] + '-' + str(attempt), 'stepfunctions', 'describe-state-machine', {'stateMachineArn': arn})
                if absent['code'] == 'StateMachineDoesNotExist':
                    CAPTURE['cleanup']['state_machines_absent'][arn] = True
                    pending.remove(arn)
            except BaseException as error:
                CAPTURE['cleanup']['errors'].append(type(error).__name__ + ': ' + str(error))
        if pending:
            time.sleep(3)
        attempt += 1
    for arn in pending:
        CAPTURE['cleanup']['state_machines_absent'][arn] = False
    if ROLE_CREATED:
        try:
            output(observe('cleanup-delete-role', 'iam', 'delete-role', {'RoleName': ROLE}))
            absent = observe('cleanup-absence-role', 'iam', 'get-role', {'RoleName': ROLE})
            CAPTURE['cleanup']['roles_absent'][ROLE] = absent['code'] == 'NoSuchEntity'
        except BaseException as error:
            CAPTURE['cleanup']['errors'].append(type(error).__name__ + ': ' + str(error))
    CAPTURE['finished_at'] = datetime.now(timezone.utc).isoformat()
    save()

"""AWS CLI transport shared by native behavior probes.

Callers own endpoint/retry choices, observations and resource cleanup. JSON shapes
remain open because probes deliberately exercise invalid and newly added inputs.
"""
import ast
import json
import re
import subprocess
from collections.abc import Mapping, Sequence
from typing import Any, NotRequired, TypedDict


class ProbeResult(TypedDict):
    code: str
    output: NotRequired[dict[str, Any]]
    error: NotRequired[dict[str, Any]]
    message: NotRequired[str]
    http_status: NotRequired[int]


class CLITimeout(RuntimeError):
    """A bounded CLI call expired; command arguments may contain secrets."""


class AWSCLIError(RuntimeError):
    """A failed strict call, retaining native JSON error fields for its caller."""

    def __init__(self, service: str, operation: str, stderr: str, details: dict[str, Any]):
        super().__init__(f"{service}:{operation}: {stderr.strip()}")
        self.details = details


def run(service: str, operation: str, parameters: Mapping[str, Any] | None = None,
        env: Mapping[str, str] | None = None, *, options: Sequence[str] = (),
        timeout: float | None = None) -> subprocess.CompletedProcess[str]:
    """Execute one CLI command without interpreting service or client failures."""
    command = ["aws", service, operation, "--output", "json", "--no-cli-pager"]
    if parameters is not None:
        command += ["--cli-input-json", json.dumps(parameters)]
    try:
        return subprocess.run(command + list(options), env=env, capture_output=True,
                              text=True, check=False, timeout=timeout)
    except subprocess.TimeoutExpired:
        raise CLITimeout("AWS CLI timed out during " + operation) from None


def call(service: str, operation: str, parameters: Mapping[str, Any] | None = None,
         env: Mapping[str, str] | None = None, *, paginate: bool = True,
         error_format: str | None = None) -> dict[str, Any]:
    """Return JSON output; service and CLI-validation errors retain typed details.

    Configuration and transport failures abort capture instead of becoming
    observations of AWS behavior. AWS CLI uses 252 for input errors and 254
    for service errors.
    """
    options = ["--cli-connect-timeout", "10", "--cli-read-timeout", "30"]
    if error_format is not None:
        options += ["--cli-error-format", error_format]
    if not paginate:
        options.append("--no-paginate")
    process = run(service, operation, parameters or None, env, options=options)
    if process.returncode:
        diagnosis = f"{service}:{operation}: {process.stderr.strip()}"
        if error_format == "json" and process.returncode in (252, 254):
            try:
                details = json.loads(process.stderr)
            except json.JSONDecodeError:
                raise RuntimeError(diagnosis) from None
            if isinstance(details, dict) and isinstance(details.get("Code"), str):
                raise AWSCLIError(service, operation, process.stderr, details)
        raise RuntimeError(diagnosis)
    return result(process)["output"]


def observe(service: str, operation: str, parameters: Mapping[str, Any] | None = None,
            env: Mapping[str, str] | None = None, *, paginate: bool = True) -> ProbeResult:
    """Capture native JSON success/error fields; callers own output redaction."""
    try:
        output = call(service, operation, parameters, env, paginate=paginate, error_format="json")
    except AWSCLIError as error:
        return {"code": error.details["Code"], "error": error.details}
    return {"code": "Success", "output": output}


def _text_error(stderr: str) -> tuple[str, str | None]:
    match = re.search(r"An error occurred \(([^)]+)\)(?:.*?operation(?: \([^)]*\))?: (.*))?", stderr)
    return (match[1], match[2]) if match else ("CLIError", None)


def result(process: subprocess.CompletedProcess[str], *, cli_error: str = "CLIError",
           cli_message: str | None = "AWS CLI failed; raw diagnostics discarded",
           debug: bool = False) -> ProbeResult:
    """Decode an observation, separating modeled errors from CLI rejection.

    A None client message retains the final three diagnostic lines for probes
    whose captured CLI-validation observations include those lines.
    """
    if process.returncode:
        code, message = _text_error(process.stderr)
        decoded: ProbeResult = {
            "code": code if message is not None else cli_error,
            "message": message if message is not None else cli_message if cli_message is not None
            else " ".join(process.stderr.splitlines()[-3:]),
        }
    else:
        decoded = {"code": "Success", "output": json.loads(process.stdout) if process.stdout.strip() else {}}
    if debug:
        statuses = re.findall(r'"[A-Z]+ [^"\r\n]* HTTP/1\.[01]" (\d{3})', process.stderr)
        if statuses:
            decoded["http_status"] = int(statuses[-1])
    return decoded


def error_code(process: subprocess.CompletedProcess[str]) -> str:
    """Decode code-only observations, including CLI ParamValidation errors."""
    return _text_error(process.stderr)[0]


def raw_xml(process: subprocess.CompletedProcess[str]) -> bytes | None:
    """Extract the last XML response from CLI debug output; discard other logs."""
    raw = None
    for line in process.stderr.splitlines():
        if line.startswith(("b'<", 'b"<')):
            try:
                candidate = ast.literal_eval(line)
                if candidate.startswith(b"<"):
                    raw = candidate
            except (ValueError, SyntaxError):
                pass
    return raw
